queries.pattern:
// Offers that can hold a pattern: a node with at least 8 GPUs and an RDMA or GPU NIC,
// under an offer that also has a Hyperdisk ML pool; with where each lives and how many
// nodes quota allows. Change the numbers and types to ask for something else.
MATCH (o:Vertex {type: 'offer'})-[:Contains]->(p:Vertex {type: 'placement'})-[:Contains]->(n:Vertex {type: 'node'})
MATCH (n)-[:Contains]->(nic:Vertex {type: 'nic'})
WHERE o.gpus >= 8 AND nic.kind IN ['rdma', 'tcpx', 'tcpxo']
MATCH (o)-[:Contains]->(pool:Vertex {type: 'hyperdisk_ml'})
RETURN o.region AS region, o.zone AS zone, o.machine_type AS machine_type, o.gpus AS gpus,
       o.egress_gbps AS egress_gbps, collect(DISTINCT nic.kind + ' x' + CAST(nic.count AS STRING) + ' @' + CAST(nic.size AS STRING) + 'Gbps') AS nics,
       p.count * n.count AS nodes, pool.size AS hyperdisk_ml_gb
ORDER BY zone, machine_type;

queries.shapes:
// Node shapes: each distinct node subtree, how widely it occurs, and which machine types
// carry it. A shape carried by several machine types is a motif; a machine type with
// several shapes is a type whose hardware varies.
MATCH (n:Vertex {type: 'node'})-[:HasShape]->(s:Shape)
MATCH (o:Vertex {type: 'offer'})-[:Contains]->(:Vertex {type: 'placement'})-[:Contains]->(n)
RETURN s.signature AS shape, s.description AS description,
       count(DISTINCT o.machine_type) AS machine_types,
       count(DISTINCT o.zone) AS zones, count(DISTINCT o.region) AS regions,
       sum(n.count) AS nodes,
       collect(DISTINCT o.machine_type)[0:6] AS examples
ORDER BY machine_types DESC, nodes DESC
LIMIT 25;

queries.summary:
// What the database holds: per graph and vertex type, the folded rows and the siblings
// they stand for (a row with count 96 is 96 identical vertices under one parent).
MATCH (v:Vertex)
RETURN v.graph AS graph, v.type AS type, count(*) AS rows, sum(v.count) AS folded_siblings
ORDER BY graph, rows DESC;

queries.varying:
// Machine types whose node shape is not the same everywhere it appears: more than one
// signature across the loaded graphs (for example E2 on AMD versus Intel hosts, or the
// same type captured in two databases with different results).
MATCH (o:Vertex {type: 'offer'})-[:Contains]->(:Vertex {type: 'placement'})-[:Contains]->(n:Vertex {type: 'node'})-[:HasShape]->(s:Shape)
WITH o.machine_type AS machine_type, collect(DISTINCT s.signature) AS shapes, collect(DISTINCT o.graph) AS graphs
WHERE size(shapes) > 1
RETURN machine_type, size(shapes) AS shapes, graphs
ORDER BY machine_type;
